$('annotation-form').addEventListener('submit',event=>{event.preventDefault();if(!state.pending)return;const a=readFields(state.pending,'new');if(!a||a.kind==='text'&&!a.name.trim()){toast('Írd be a felirat szövegét.');return;}pushUndo();state.doc.annotations.push(a);state.selected=a.id;state.pending=null;state.draft=[];persist();$('annotation-dialog').close();renderAll();setMobilePanel('marks');toast(labels[a.kind]+' hozzáadva.');});
