const mobileQuery=matchMedia('(max-width:900px)');
function setMobilePanel(panel){
 if(!mobileQuery.matches)return;
 document.body.dataset.mobilePanel=panel;
 for(const name of['map','generator','marks']){const element=$(name+'-panel');element.inert=name!==panel;element.setAttribute('role','tabpanel');element.setAttribute('aria-labelledby','mobile-'+name);}
 document.querySelectorAll('.mobile-nav [data-mobile-panel]').forEach(button=>{button.setAttribute('aria-selected',String(button.dataset.mobilePanel===panel));button.tabIndex=button.dataset.mobilePanel===panel?0:-1;});requestAnimationFrame(applyTransform);
}
function configureMobile(){
 if(mobileQuery.matches)setMobilePanel(document.body.dataset.mobilePanel||'map');
 else{delete document.body.dataset.mobilePanel;for(const id of['map-panel','generator-panel','marks-panel']){$(id).inert=false;$(id).removeAttribute('role');$(id).removeAttribute('aria-labelledby');}}
 applyTransform();
}
mobileQuery.addEventListener('change',configureMobile);
document.querySelectorAll('.mobile-nav [data-mobile-panel]').forEach(button=>{button.addEventListener('click',()=>setMobilePanel(button.dataset.mobilePanel));button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();const tabs=[...document.querySelectorAll('.mobile-nav [data-mobile-panel]')],index=tabs.indexOf(button),next=tabs[(index+(event.key==='ArrowRight'?1:2))%tabs.length];setMobilePanel(next.dataset.mobilePanel);next.focus();});});
function toggleMapFocus(force){const active=force??!document.body.classList.contains('map-focus');setMobilePanel('map');document.body.classList.toggle('map-focus',active);document.querySelector('.site-header').inert=active;document.querySelector('.mobile-nav').inert=active;if(active){$('generator-panel').inert=true;$('marks-panel').inert=true;}else configureMobile();$('map-focus').setAttribute('aria-pressed',String(active));$('map-focus').setAttribute('aria-label',active?'Kilépés a teljes képernyőből':'Teljes képernyő');$('map-focus').title=active?'Kilépés a teljes képernyőből':'Teljes képernyő';requestAnimationFrame(applyTransform);}
$('map-focus').addEventListener('click',()=>toggleMapFocus());
const viewport=$('map-viewport'),touches=new Map();let pinch=null,gestureBlocking=false;
function viewPoint(event){const svg=$('map-render').querySelector('svg'),p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());}
function touchState(){const ps=[...touches.values()],a=viewPoint(ps[0]),b=viewPoint(ps[1]);return{midpoint:{x:(a.x+b.x)/2,y:(a.y+b.y)/2},distance:Math.hypot(a.x-b.x,a.y-b.y)};}
viewport.addEventListener('pointerdown',event=>{
 if(event.button!==0||event.target.closest('.zoom-toolbar,.map-context'))return;
 if(event.pointerType==='touch'){
  touches.set(event.pointerId,{clientX:event.clientX,clientY:event.clientY});
  if(touches.size===2){
   if(pointer?.dragging&&pointer.annotation&&pointer.operation!=='pan')state.doc.annotations=state.doc.annotations.map(a=>a.id===pointer.annotation.id?pointer.annotation:a);
   renderMap();pinch={...touchState(),zoom:state.zoom,pan:{...state.pan}};gestureBlocking=true;pointer=null;suppressClick=true;$('map-context').hidden=true;
   for(const id of touches.keys())viewport.setPointerCapture(id);return;
  }
  if(touches.size>2)return;
 }
 const world=mapPoint(event),handle=event.target.closest('[data-vertex]'),mark=event.target.closest('[data-annotation]'),a=state.doc.annotations.find(a=>a.id===(handle?.dataset.owner||mark?.dataset.annotation));let operation='pan';
 if(!state.player&&state.tool==='select'&&a){if(handle)operation='vertex';else if(a.kind==='building'&&(a.buildingId||a.roomId))operation='pan';else operation='annotation';}
 pointer={id:event.pointerId,x:event.clientX,y:event.clientY,world,pan:{...state.pan},operation,annotation:a?structuredClone(a):null,vertex:handle?+handle.dataset.vertex:null,before:null,dragging:false};
});
viewport.addEventListener('pointermove',event=>{
 if(touches.has(event.pointerId))touches.set(event.pointerId,{clientX:event.clientX,clientY:event.clientY});
 if(pinch&&touches.size>=2){const view=pinchView(pinch,touchState());state.zoom=view.zoom;state.pan=view.pan;applyTransform();return;}
 if(!pointer||pointer.id!==event.pointerId)return;const dx=event.clientX-pointer.x,dy=event.clientY-pointer.y;
 if(!pointer.dragging&&Math.hypot(dx,dy)>6){pointer.dragging=true;pointer.before=snapshot(state.doc,state.savedId);viewport.setPointerCapture(event.pointerId);viewport.classList.add('dragging');$('map-context').hidden=true;}
 if(!pointer.dragging)return;
 if(pointer.operation==='pan'){const rect=viewport.getBoundingClientRect(),scale=Math.min(rect.width/1000,rect.height/760);state.pan={x:pointer.pan.x+dx/scale,y:pointer.pan.y+dy/scale};applyTransform();return;}
 const position=mapPoint(event),original=pointer.annotation;state.selected=original.id;let updated=structuredClone(original);
 if(pointer.operation==='vertex')updated.points[pointer.vertex]=snapPoint(position,original.id);
 else if(original.kind==='district'){let mx=position.x-pointer.world.x,my=position.y-pointer.world.y;mx=clamp(mx,-Math.min(...original.points.map(p=>p.x)),1000-Math.max(...original.points.map(p=>p.x)));my=clamp(my,-Math.min(...original.points.map(p=>p.y)),760-Math.max(...original.points.map(p=>p.y)));updated.points=original.points.map(p=>({x:p.x+mx,y:p.y+my}));}
 else{updated.x=clamp(original.x+position.x-pointer.world.x,0,1000);updated.y=clamp(original.y+position.y-pointer.world.y,0,760);}
 state.doc.annotations=state.doc.annotations.map(a=>a.id===updated.id?updated:a);renderMap();
});
function finishPointer(event,cancel=false){
 touches.delete(event.pointerId);
 if(gestureBlocking){if(touches.size<2){pinch=null;pointer=null;viewport.classList.remove('dragging');updateHandles();}if(!touches.size){gestureBlocking=false;setTimeout(()=>{suppressClick=false;},200);}return;}
 if(!pointer||pointer.id!==event.pointerId)return;const p=pointer;
 if(p.dragging){suppressClick=true;setTimeout(()=>{suppressClick=false;},150);if(viewport.hasPointerCapture(event.pointerId))viewport.releasePointerCapture(event.pointerId);
  if(p.operation!=='pan'){const a=state.doc.annotations.find(a=>a.id===p.annotation.id);if(cancel||a.kind==='district'&&!validPolygon(a.points)){state.doc.annotations=state.doc.annotations.map(a=>a.id===p.annotation.id?p.annotation:a);if(!cancel)toast('A határ nem keresztezheti saját magát.');}else{pushUndo(p.before);persist();}renderAll();}
 }
 pointer=null;viewport.classList.remove('dragging');
}
viewport.addEventListener('pointerup',event=>finishPointer(event));viewport.addEventListener('pointercancel',event=>finishPointer(event,true));viewport.addEventListener('pointerleave',()=>{if(pointer&&!pointer.dragging&&!touches.size)pointer=null;});
viewport.addEventListener('wheel',event=>{if(!event.ctrlKey&&!event.metaKey)return;event.preventDefault();setZoom(state.zoom+(event.deltaY<0?.15:-.15),viewPoint(event));},{passive:false});
document.addEventListener('keydown',event=>{if(isTyping(event.target))return;if(event.key==='Escape'){if(document.body.classList.contains('map-focus')){toggleMapFocus(false);return;}$('map-context').hidden=true;$('export-menu').hidden=true;if(state.draft.length){state.draft=[];renderMap();renderToolState();}else setTool('select');return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();historyStep(event.shiftKey);return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();historyStep(true);return;}if(document.querySelector('dialog[open]'))return;if(!state.player&&state.tool==='district'&&event.key==='Enter'){event.preventDefault();finishDistrict();return;}if(!state.player&&state.tool==='district'&&event.key==='Backspace'){event.preventDefault();state.draft.pop();renderToolState();renderMap();return;}if(event.key==='Delete'){event.preventDefault();deleteSelected();return;}if(event.ctrlKey||event.metaKey||event.altKey)return;const tools={v:'select',h:'pan',p:'pin',b:'building',n:'district',t:'text'};if(tools[event.key.toLowerCase()]&&!state.player)setTool(tools[event.key.toLowerCase()]);if(event.key==='+'||event.key==='=')setZoom(state.zoom+.25);if(event.key==='-')setZoom(state.zoom-.25);if(event.key==='0')resetZoom();});
document.addEventListener('crowcity-language',()=>{renderAll();if($('saved-dialog').open)renderSaved();});
initialize();configureMobile();initI18n();
